package com.phoenix.business.domain;
import com.fasterxml.jackson.annotation.JsonIgnore; import jakarta.persistence.*; import lombok.*; import java.time.Instant;
@Entity @Table(name="users") @Getter @Setter @NoArgsConstructor
public class User { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,unique=true) private String username; @JsonIgnore @Column(name="password_hash",nullable=false) private String passwordHash; @Column(name="display_name",nullable=false) private String displayName; @Enumerated(EnumType.STRING) @Column(nullable=false) private Role role; @Column(nullable=false) private boolean active=true; @Column(name="force_password_change",nullable=false) private boolean forcePasswordChange=true; @Column(name="last_login_at") private Instant lastLoginAt; @Column(name="created_at",insertable=false,updatable=false) private Instant createdAt; @Column(name="updated_at",insertable=false,updatable=false) private Instant updatedAt; public enum Role {OWNER,ADMIN,STAFF} }
